import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    t = int(next(iterator))
    results = []

    for _ in range(t):
        n = int(next(iterator))
        b = [int(next(iterator)) for _ in range(n)]
        p = [int(next(iterator)) for _ in range(n)]

        parent = [0] * (n + 1)
        for i in range(n):
            u = i + 1
            parent[u] = b[i]

        root = None
        for i in range(1, n + 1):
            if parent[i] == i:
                root = i
                break

        pos = [0] * (n + 1)
        for i, v in enumerate(p):
            pos[v] = i

        possible = True
        for i in range(1, n + 1):
                if i == root:
                    continue
                par = parent[i]
                if pos[par] > pos[i]:
                    possible = False
                    break

        if not possible:
            results.append("-1")
            continue

        dist = [0] * (n + 1)
        w = [0] * (n + 1)

        for i in range(n):
            u = p[i]
            if u == root:
                dist[u] = 0
                continue

            par = parent[u]
            if dist[par] == 0 and par != root:
                pass

            needed = dist[par] + 1
            if i > 0:
                prev_u = p[i-1]
                if dist[prev_u] >= needed:
                    needed = dist[prev_u] + 1

            w[u] = needed - dist[par]
            dist[u] = needed

        if any(w[u] < 1 for u in range(1, n+1) if u != root):
            results.append("-1")
            continue

        if any(w[u] > 10**9 for u in range(1, n+1)):
            results.append("-1")
            continue

        current_dist = [0] * (n + 1)
        for i_u, u in enumerate(p):
            if u == root:
                current_dist[u] = 0
            else:
                current_dist[u] = current_dist[parent[u]] + w[u]

        ok = True
        for i in range(n - 1):
            if current_dist[p[i]] >= current_dist[p[i+1]]:
                ok = False
                break

        if not ok:
            results.append("-1")
        else:
            res_w = [0] * n
            for i in range(n):
                u = i + 1
                res_w[i] = w[u]
            results.append(" ".join(map(str, res_w)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
